SELECT DISTINCT ?item ?itemLabel WHERE {
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],mul,en". }
  {
    SELECT DISTINCT ?item WHERE {
      ?item p:P570 ?statement.
      ?statement psv:P570 ?value.
      ?value wikibase:timePrecision ?precision.
      hint:Prior hint:rangeSafe "true"^^xsd:boolean.
      FILTER(?precision >= 9)
      ?value wikibase:timeValue ?death.
      hint:Prior hint:rangeSafe "true"^^xsd:boolean.
      FILTER(?death < "+1999-06-25T00:00:00Z"^^xsd:dateTime)
        ?item p:P27 ?statement1.
      ?statement1 (ps:P27/(wdt:P279*)) wd:Q211.
    }
    LIMIT 100
  }
}

